The solution involves partitioning the array into groups where each group contains elements that have the same value when divided by 4 (i.e., the same higher bits). Within each group, elements can be freely swapped because their XOR is always less than 4. The lexicographically smallest array is achieved by sorting the elements within each group while maintaining the relative order of groups since elements from different groups cannot be swapped.

For each test case:
1. Read the array.
2. Group the indices of elements by their key (value shifted right by 2 bits).
3. For each group, collect the values, sort them, and assign them back to the indices in the group in the order the indices appear (which is already sorted since indices are processed in increasing order).

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <map>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n);
        for (int i = 0; i < n; i++) {
            cin >> a[i];
        }

        map<int, vector<int>> groups;
        for (int i = 0; i < n; i++) {
            int key = a[i] >> 2;
            groups[key].push_back(i);
        }

        vector<int> res(n);
        for (auto &p : groups) {
            vector<int> &indices = p.second;
            vector<int> values;
            for (int idx : indices) {
                values.push_back(a[idx]);
            }
            sort(values.begin(), values.end());
            for (int j = 0; j < indices.size(); j++) {
                res[indices[j]] = values[j];
            }
        }

        for (int i = 0; i < n; i++) {
            cout << res[i] << " ";
        }
        cout << "\n";
    }
    return 0;
}
