The solution involves counting the number of lattice points that lie in the annulus between two circles of radii \(r\) and \(r+1\). For each test case, we compute the number of points inside the circle of radius \(r+1\) excluding the boundary, denoted \(C(r+1)\), and subtract the number of points inside the circle of radius \(r\) excluding the boundary, denoted \(C(r)\). The function \(C(R)\) is computed by iterating over \(x\) from 1 to \(R-1\), calculating the maximum \(y\) for each \(x\) such that \(x^2 + y^2 < R^2\), and accounting for both positive and negative \(x\) and \(y\) values.

```cpp
#include <iostream>
#include <cmath>
using namespace std;

typedef long long ll;

ll C(ll R) {
    if (R == 0) return 0;
    ll total = 2 * R - 1; // Points for x=0
    ll count_pos = 0;
    for (ll x = 1; x < R; x++) {
        ll M = R * R - x * x;
        ll s = sqrt(M);
        if (s * s > M) s--; // Ensure s is the integer square root
        if (s * s == M) {
            count_pos += 2 * s - 1;
        } else {
            count_pos += 2 * s + 1;
        }
    }
    total += 2 * count_pos; // Account for both positive and negative x
    return total;
}

