using namespace std;

typedef long long ll;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int t;
    cin >> t;
    while (t--) {
        ll n, k;
        cin >> n >> k;
        vector<ll> a(n);
        for (int i = 0; i < n; i++) {
            cin >> a[i];
        }
        sort(a.begin(), a.end());
        ll S = accumulate(a.begin(), a.end(), 0LL);
        vector<ll> pre(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            pre[i] = pre[i - 1] + a[i - 1];
        }

        ll low = a[0];
        ll high = a[0] + k + 1;
        while (low <= high) {
            ll mid = low + (high - low) / 2;
            auto it = upper_bound(a.begin(), a.end(), mid);
            ll idx = it - a.begin();
            ll f_val = idx * mid - pre[idx];
            if (f_val <= k) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        ll T = S + k;
        ll W = min(T - n + 1, n * high);
        cout << W << "\n";
    }

    return 0;
}
